      "expected": "These Ethernet transmit pins should be connected to the RJ45 jack or left unconnected, not tied to ground.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(node (ref \"U10\") (pin \"13\") (pinfunction \"LAN_PORT3_TX+\") (pintype \"bidirectional\"))"
